-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

SET allow_experimental_variant_type = 1;
SET allow_suspicious_variant_types = 1;

-- Bool is a custom-named UInt8, and the ORC writer maps Bool -> BOOLEAN while a plain UInt8 goes
-- to BYTE. The union branch-hint matcher must preserve that distinction, otherwise both branches
-- of union<boolean, tinyint> match both alternatives of Variant(Bool, UInt8), no hint is assigned,
-- and the final Variant(Bool, Int8) -> Variant(Bool, UInt8) conversion fails.

-- union<boolean, tinyint> read as Variant(Bool, UInt8). Rows: true, 5, false, -6, NULL (a null
-- payload in the boolean branch). The tinyint branch takes the UInt8 alternative, so -6 -> 250.
SELECT u, toTypeName(u) FROM format(ORC, 'u Variant(Bool, UInt8)', unhex('')) ORDER BY toString(u);

-- The same file with the inferred schema: BOOLEAN -> Bool, BYTE -> Int8, so -6 stays -6.
SELECT u, toTypeName(u) FROM format(ORC, unhex('')) ORDER BY toString(u);

-- The same file read as Variant(Bool, Int8) explicitly.
SELECT u, toTypeName(u) FROM format(ORC, 'u Variant(Bool, Int8)', unhex('')) ORDER BY toString(u);

-- A boolean branch can still take a plain UInt8 alternative when that is unambiguous.
-- union<boolean, string> read as Variant(UInt8, String). Rows: true, 'x', false -> 1, x, 0.
SELECT u, toTypeName(u) FROM format(ORC, 'u Variant(UInt8, String)', unhex('')) ORDER BY toString(u);

-- union<boolean, string> read as Variant(Bool, String). Rows: true, 'x', false.
SELECT u, toTypeName(u) FROM format(ORC, 'u Variant(Bool, String)', unhex('')) ORDER BY toString(u);
